From 94f5635298a2811d23c7cad16c5cdac82ff0fa08 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:03:54 +0100
Subject: [PATCH] applets/digital-clock: allow giving time zones custom names

Time zones could only be shown by their code, city or offset, so users
had to remember that "Chicago" meant Houston. Each configured time zone
can now be renamed, and the name is shown in the panel, tooltip and popup.

BUG: 395164
---
 applets/digital-clock/CalendarView.qml    | 11 +----
 applets/digital-clock/DigitalClock.qml    | 17 ++-----
 applets/digital-clock/Tooltip.qml         | 11 +----
 applets/digital-clock/configTimeZones.qml | 60 ++++++++++++++++++++++-
 applets/digital-clock/main.qml            | 18 +++++++
 applets/digital-clock/main.xml            |  4 ++
 6 files changed, 88 insertions(+), 33 deletions(-)

diff --git a/applets/digital-clock/CalendarView.qml b/applets/digital-clock/CalendarView.qml
index 48d5dcccb7..a99677636a 100644
--- a/applets/digital-clock/CalendarView.qml
+++ b/applets/digital-clock/CalendarView.qml
@@ -500,16 +500,7 @@ PlasmaExtras.Representation {
                     required property string modelData

                     readonly property bool isCurrentTimeZone: tzClock.timeZone == root.currentTimeZone
-                    readonly property string tzLabel: {
-                        switch (Plasmoid.configuration.displayTimezoneFormat) {
-                        case 0: // Code
-                            return tzClock.timeZoneCode;
-                        case 1: // City
-                            return TimeZonesI18n.i18nCity(tzClock.timeZone);
-                        case 2: // Offset from UTC time
-                            return tzClock.timeZoneOffset;
-                        }
-                    }
+                    readonly property string tzLabel: root.timeZoneLabel(tzClock)

                     width: ListView.view.width - ListView.view.leftMargin - ListView.view.rightMargin

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..69825918b9 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -113,6 +113,10 @@ MouseArea {
             main.setupLabels();
         }

+        function onCustomTimeZoneNamesChanged() {
+            main.setupLabels();
+        }
+
         function onLastSelectedTimezoneChanged() {
             main.timeFormatCorrection();
         }
@@ -560,18 +564,7 @@ MouseArea {
         let timezoneString = "";

         if (showTimezone) {
-            // format time zone as tz code, city or UTC offset
-            switch (Plasmoid.configuration.displayTimezoneFormat) {
-            case 0: // Code
-                timezoneString = clock.timeZoneCode;
-                break;
-            case 1: // City
-                timezoneString = TimeZonesI18n.i18nCity(clock.timeZone);
-                break;
-            case 2: // Offset from UTC time
-                timezoneString = clock.timeZoneOffset;
-                break;
-            }
+            timezoneString = root.timeZoneLabel(clock);
             if ((Plasmoid.configuration.showDate || oneLineMode) && Plasmoid.formFactor === PlasmaCore.Types.Horizontal) {
                 timezoneString = `(${timezoneString})`;
             }
diff --git a/applets/digital-clock/Tooltip.qml b/applets/digital-clock/Tooltip.qml
index 7ecafd0baf..419b84decc 100644
--- a/applets/digital-clock/Tooltip.qml
+++ b/applets/digital-clock/Tooltip.qml
@@ -134,16 +134,7 @@ Item {
                     required property int index
                     required property string modelData

-                    readonly property string tzLabel: {
-                        switch (Plasmoid.configuration.displayTimezoneFormat) {
-                        case 0: // Code
-                            return tzClock.timeZoneCode;
-                        case 1: // City
-                            return TimeZonesI18n.i18nCity(tzClock.timeZone);
-                        case 2: // Offset from UTC time
-                            return tzClock.timeZoneOffset;
-                        }
-                    }
+                    readonly property string tzLabel: root.timeZoneLabel(tzClock)

                     // Layout.fillWidth is buggy here
                     Layout.alignment: index % 2 === 0 ? Qt.AlignRight : Qt.AlignLeft
diff --git a/applets/digital-clock/configTimeZones.qml b/applets/digital-clock/configTimeZones.qml
index 93f7c38782..9ef9d4328b 100644
--- a/applets/digital-clock/configTimeZones.qml
+++ b/applets/digital-clock/configTimeZones.qml
@@ -15,6 +15,7 @@ import org.kde.kirigami as Kirigami
 import org.kde.config as KConfig
 import org.kde.kcmutils as KCMUtils
 import org.kde.plasma.workspace.timezoneselector as TimeZone
+import org.kde.plasma.clock

 Kirigami.PageRow {
     id: timeZonesRow
@@ -23,6 +24,20 @@ Kirigami.PageRow {
     property string cfg_lastSelectedTimezone
     property alias cfg_selectedTimeZones: timeZones.selectedTimeZones
     property alias cfg_wheelChangesTimezone: enableWheelCheckBox.checked
+    property list<string> cfg_customTimeZoneNames
+
+    function customName(timeZoneId: string): string {
+        const entry = cfg_customTimeZoneNames.find(entry => entry.startsWith(timeZoneId + "="));
+        return entry ? entry.slice(timeZoneId.length + 1) : "";
+    }
+
+    function setCustomName(timeZoneId: string, name: string): void {
+        const names = cfg_customTimeZoneNames.filter(entry => !entry.startsWith(timeZoneId + "="));
+        if (name.trim().length > 0) {
+            names.push(timeZoneId + "=" + name.trim());
+        }
+        cfg_customTimeZoneNames = names;
+    }

     defaultColumnWidth: timeZonesRow.width
     globalToolBar.style: Kirigami.ApplicationHeaderStyle.Auto
@@ -104,6 +119,38 @@ Kirigami.PageRow {
             }
         ]

+        Clock {
+            id: systemClock
+        }
+
+        Kirigami.PromptDialog {
+            id: renameDialog
+
+            property string timeZoneId
+            property string city
+
+            title: i18nc("@title:window", "Rename Time Zone")
+            subtitle: i18nc("@info %1 is a city name", "Leave empty to show it as “%1”.", city)
+            standardButtons: Kirigami.Dialog.Ok | Kirigami.Dialog.Cancel
+
+            function openFor(timeZoneId: string, city: string): void {
+                renameDialog.timeZoneId = timeZoneId;
+                renameDialog.city = city;
+                nameField.text = timeZonesRow.customName(timeZoneId);
+                open();
+                nameField.forceActiveFocus();
+                nameField.selectAll();
+            }
+
+            onAccepted: timeZonesRow.setCustomName(timeZoneId, nameField.text)
+
+            QQC2.TextField {
+                id: nameField
+                placeholderText: renameDialog.city
+                onAccepted: renameDialog.accept()
+            }
+        }
+
         TimeZoneModel {
             id: timeZones

@@ -138,6 +185,8 @@ Kirigami.PageRow {

                 readonly property bool isCurrent: timeZonesRow.cfg_lastSelectedTimezone === model.timeZoneId
                 readonly property bool isIdenticalToLocal: !model.isLocalTimeZone && model.city === timeZones.localTimeZoneCity()
+                readonly property string resolvedTimeZoneId: model.isLocalTimeZone ? String(systemClock.timeZone) : model.timeZoneId
+                readonly property string customName: timeZonesRow.customName(resolvedTimeZoneId)

                 width: ListView.view.width

@@ -146,7 +195,7 @@ Kirigami.PageRow {
                 // Stripes help the eye line up the text on the left and the button on the right
                 Kirigami.Theme.useAlternateBackgroundColor: true

-                text: model.city
+                text: customName ? i18nc("@item:inlistbox %1 is a name chosen by the user, %2 is the time zone's city", "%1 (%2)", customName, model.city) : model.city
                 subtitle: {
                     if (configuredTimeZoneList.count > 1) {
                         if (isCurrent) {
@@ -188,6 +237,15 @@ Kirigami.PageRow {
                         onClicked: KCMUtils.KCMLauncher.openSystemSettings("kcm_clock")
                     }

+                    QQC2.Button {
+                        icon.name: "edit-rename"
+                        font.bold: false
+                        onClicked: renameDialog.openFor(timeZoneListItem.resolvedTimeZoneId, timeZoneListItem.model.city)
+                        QQC2.ToolTip {
+                            text: i18n("Rename this time zone")
+                        }
+                    }
+
                     QQC2.Button {
                         visible: !timeZoneListItem.model.isLocalTimeZone && configuredTimeZoneList.count > 1
                         icon.name: "edit-delete-remove"
diff --git a/applets/digital-clock/main.qml b/applets/digital-clock/main.qml
index 5b983ef25b..736cd6eee4 100644
--- a/applets/digital-clock/main.qml
+++ b/applets/digital-clock/main.qml
@@ -93,6 +93,24 @@ PlasmoidItem {
         }
     }

+    function timeZoneLabel(clock: Clock): string {
+        const timeZone = String(clock.timeZone);
+        const customName = Plasmoid.configuration.customTimeZoneNames.find(entry => entry.startsWith(timeZone + "="));
+        if (customName) {
+            return customName.slice(timeZone.length + 1);
+        }
+
+        switch (Plasmoid.configuration.displayTimezoneFormat) {
+        case 0: // Code
+            return clock.timeZoneCode;
+        case 1: // City
+            return TimeZonesI18n.i18nCity(timeZone);
+        case 2: // Offset from UTC time
+            return clock.timeZoneOffset;
+        }
+        return "";
+    }
+
     function selectedTimeZonesDeduplicatingExplicitLocalTimeZone():/* [string] */var {
         /*
          * Don't add this item if it's the same as the local time zone, which
diff --git a/applets/digital-clock/main.xml b/applets/digital-clock/main.xml
index 6716b906c5..b93003a65f 100644
--- a/applets/digital-clock/main.xml
+++ b/applets/digital-clock/main.xml
@@ -69,6 +69,10 @@
     <entry name="lastSelectedTimezone" type="String">
       <label>When multiple time zones are configured, this is the one shown on widget restore. Typically the system's current time zone.</label>
       <default>Local</default>
+    </entry>
+    <entry name="customTimeZoneNames" type="StringList">
+      <label>Names chosen by the user for time zones, shown instead of their code, city or UTC offset. Format is "America/Chicago=Houston".</label>
+      <default></default>
     </entry>
         <entry name="wheelChangesTimezone" type="Bool">
       <label>Whether the mouse wheel switches between the time zones configured in selectedTimeZones.</label>
-- 
2.53.0
